<?php
declare(strict_types=1);
if(getenv('SLS_TEST_NAMESPACE')!=='entered'){throw new RuntimeException('Use isolated wrapper.');}
require dirname(__DIR__).'/slsmassnotifyserver/AutomationService.php';
require dirname(__DIR__).'/slsmassnotifyserver/EnterpriseIntegrationsService.php';
use SLS\MassNotify\{AutomationConfig,AutomationInputs,AutomationService,AutomationStore,EnterpriseIntegrationsService,EnterpriseIntegrationsStore,LocationDirectory};
$root=sys_get_temp_dir().'/sls-trigger-admission-proof-'.bin2hex(random_bytes(8));mkdir($root,0700);$checks=0;
function check(bool$value,string$name):void{global$checks;$checks++;if(!$value){throw new RuntimeException($name);}}
function proof(array$rule,array$body,int$stamp):array{$raw=json_encode($body,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);return['raw'=>$raw,'headers'=>['timestamp'=>(string)$stamp,'signature'=>hash_hmac('sha256',$rule['id'].'.'.$stamp.'.'.$raw,$rule['secret'])]];}
try{
 $now=time();$action=AutomationConfig::action(['id'=>'act_'.str_repeat('a',24),'name'=>'Inert action','enabled'=>true,'kind'=>'brightsign_udp','host'=>'192.168.1.20','port'=>5000,'message'=>'fixture']);$rule=AutomationConfig::rule(['id'=>'trg_'.str_repeat('b',24),'name'=>'Private sensor','kind'=>'sensor','secret'=>str_repeat('c',64),'enabled'=>true,'event'=>'smoke','action_ids'=>[$action['id']],'allow_tests'=>true]);$settings=['runtime_enabled'=>true,'automations'=>['schema'=>1,'rules'=>[$rule],'actions'=>[$action]]];$input=['request_id'=>str_repeat('1',32),'sent_at'=>$now,'expires_at'=>$now+300,'event'=>'smoke','message'=>'Inert fixture','is_test'=>true];$valid=proof($rule,['operation'=>'activate']+$input,$now);
 foreach(['valid','expired','future','rotated','tampered_raw','extra_proof','extra_header','legacy_omitted']as$case){
  $current=$settings;$auth=$valid;if($case==='expired'){$auth=proof($rule,$input,$now-61);}if($case==='future'){$auth=proof($rule,$input,$now+61);}if($case==='rotated'){$current['automations']['rules'][0]['secret']=str_repeat('d',64);}if($case==='tampered_raw'){$auth['raw'].=' ';}if($case==='extra_proof'){$auth['unexpected']='no';}if($case==='extra_header'){$auth['headers']['unexpected']='no';}if($case==='legacy_omitted'){$auth=null;}
  $store=new AutomationStore($root.'/'.$case);$service=new AutomationService($store,static fn()=>$current,static function(){throw new RuntimeException('No announcement permitted.');},static function(){throw new RuntimeException('No action permitted.');},static fn()=>$now);$allowed=false;
  try{$event=$service->activate($rule['id'],$input,'sensor',$auth);$allowed=$event['state']==='queued';}catch(DomainException$error){}
  $expected=in_array($case,['valid','legacy_omitted'],true);check($allowed===$expected,'Admission proof result '.$case);check(count($store->read()['events'])===($expected?1:0),'Rejected proof created operational event '.$case);
 }
 $panic=AutomationConfig::rule(['id'=>'trg_'.str_repeat('e',24),'name'=>'Private panic','kind'=>'panic','secret'=>str_repeat('f',64),'enabled'=>true,'location_id'=>LocationDirectory::DEFAULT_SITE_ID,'action_ids'=>[$action['id']],'allow_tests'=>true]);$panicSettings=['runtime_enabled'=>true,'automations'=>['rules'=>[$panic],'actions'=>[$action]]];
 foreach(['valid'=>0,'expired'=>-61]as$case=>$offset){$store=new AutomationStore($root.'/panic-'.$case);$service=new AutomationService($store,static fn()=>$panicSettings,static function(){},static function(){},static fn()=>$now);$allowed=false;try{$service->challenge($panic['id'],str_repeat('2',32),proof($panic,['operation'=>'challenge','request_id'=>str_repeat('2',32)],$now+$offset));$allowed=true;}catch(DomainException$error){}check($allowed===($case==='valid'),'Panic proof '.$case);check(count($store->read()['challenges'])===($case==='valid'?1:0),'Rejected panic proof created challenge');}
 foreach(['valid'=>0,'expired'=>-61]as$case=>$offset){$store=new EnterpriseIntegrationsStore($root.'/heartbeat-'.$case);$service=new EnterpriseIntegrationsService($store,null,static fn()=>$now);$heartbeat=['operation'=>'heartbeat','request_id'=>str_repeat('3',32),'sent_at'=>$now,'expires_at'=>$now+60,'is_test'=>true];$allowed=false;try{$result=$service->heartbeat(['enabled'=>'1'],$rule,$heartbeat,proof($rule,$heartbeat,$now+$offset));$allowed=$result['state']==='healthy';}catch(DomainException$error){}check($allowed===($case==='valid'),'Heartbeat proof '.$case);check(count($store->read()['sensors'])===($case==='valid'?1:0),'Rejected heartbeat proof renewed health');}
 echo'SLS trigger admission proof: '.$checks." actual policy/claim/challenge/heartbeat checks passed; no transport or PBX effect.\n";
}finally{$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST);foreach($it as$f){if($f->isDir()&&!$f->isLink()){rmdir($f->getPathname());}else{unlink($f->getPathname());}}rmdir($root);}
